  select 'hzl', 'user', (select id from users where phone = '+15705557008'), 'recomendacion', null, 'Se me reventó un tubo a las 2 de la mañana. Llegaron en 40 minutos y me dieron el precio antes de tocar nada.', 'es', 'plomeria-rodriguez', array['Emergencia de plomería'], null, null, false, null, now() - interval '1320 minutes', now() - interval '1320 minutes', now() - interval '1320 minutes'
  where not exists (select 1 from com_posts where city_id = 'hzl' and body = 'Se me reventó un tubo a las 2 de la mañana. Llegaron en 40 minutos y me dieron el precio antes de tocar nada.');
insert into com_votes (target_kind, target_id, user_id, v) select 'post', (select id from com_posts where city_id = 'hzl' and body = 'Se me reventó un tubo a las 2 de la mañana. Llegaron en 40 minutos y me dieron el precio antes de tocar nada.' order by id limit 1), v.id, case when v.rn <= 35 then 1 else -1 end
  from semilla_votantes v where v.rn <= 36 and (select id from com_posts where city_id = 'hzl' and body = 'Se me reventó un tubo a las 2 de la mañana. Llegaron en 40 minutos y me dieron el precio antes de tocar nada.' order by id limit 1) is not null on conflict do nothing;
