  from semilla_votantes v where v.rn <= 5 and (select id from com_comments where post_id = (select id from com_posts where city_id = 'hzl' and body = 'Así se vio el desfile dominicano del domingo en la Broad St. Gracias a todos los que salieron con su bandera.' order by id limit 1) and body = '¡Qué bonito quedó! El año que viene salgo con los niños.' order by id limit 1) is not null on conflict do nothing;
